(() => {
  'use strict';
  const canvas=document.querySelector('#game'), ctx=canvas.getContext('2d');
  const mapCanvas=document.querySelector('#mini-map'), mapCtx=mapCanvas.getContext('2d');
  const TILE=28,SIZE=64;
  const inventory={biomass:2,crystal:0,stone:0,water:1,seed:1};
  const player={x:31,y:34,facing:1,moving:false,walk:0,oxygen:92,energy:86};
  const world={time:.25,day:1,eco:8,cameraX:0,cameraY:0,zoom:1,plants:[],buildings:[],collected:0};
  let tiles=[],nodes=[],keys={},joy={x:0,y:0},selectedBuild='seed',lastTime=0,toastTimer,actionTarget=null;
  const rnd=(s)=>{let n=s|0;return()=>{n=(n*1664525+1013904223)|0;return((n>>>0)%10000)/10000}};
  const random=rnd(381), distance=(x,y,a,b)=>Math.hypot(x-a,y-b);
  const island=(x,y)=>Math.hypot((x-31.5)/27.7,(y-32)/23.5);
  const land=(x,y)=>x>=0&&y>=0&&x<SIZE&&y<SIZE&&island(x,y)<1;
  function generate(){
    for(let y=0;y<SIZE;y++){tiles[y]=[];for(let x=0;x<SIZE;x++){const d=island(x,y),n=(Math.sin(x*1.72+y*.51)+Math.cos(y*1.21-x*.73))*.018,type=d+n>.94?'water':d>.83?'sand':'soil';tiles[y][x]={type,fertile:type==='soil'&&random()<.16,variation:random(),height:random()}}}
    nodes=[{x:33,y:31,type:'sprout'},{x:28,y:35,type:'sprout'},{x:36,y:37,type:'stone'},{x:25,y:31,type:'crystal'},{x:39,y:32,type:'water'},{x:30,y:28,type:'sprout'},{x:42,y:39,type:'stone'},{x:22,y:39,type:'crystal'},{x:34,y:42,type:'sprout'},{x:45,y:28,type:'sprout'},{x:19,y:30,type:'stone'},{x:39,y:45,type:'crystal'},{x:48,y:37,type:'sprout'},{x:26,y:44,type:'water'}];
  }
  function resize(){const d=Math.min(devicePixelRatio||1,1.5);canvas.width=innerWidth*d;canvas.height=innerHeight*d;ctx.setTransform(d,0,0,d,0,0)}
  function say(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
  const center=()=>({x:innerWidth/2,y:innerHeight/2});
  function worldPoint(){const c=center(),scale=TILE*world.zoom;return{x:(c.x-world.cameraX)/scale,y:(c.y-world.cameraY)/scale}}
  function screen(x,y){const c=center(),s=TILE*world.zoom;return{x:c.x+(x-player.x)*s,y:c.y+(y-player.y)*s}}
  function nearest(){let best=null,bd=2.1;for(const n of nodes){if(n.gone)continue;const d=distance(player.x,player.y,n.x,n.y);if(d<bd){bd=d;best=n}}actionTarget=best;const el=document.querySelector('#action-readout span:last-child');if(best){const names={sprout:'Gather glowfern · E',stone:'Gather basalt · E',crystal:'Gather prism crystal · E',water:'Collect pure water · E'};el.textContent=names[best.type]}else if(selectedBuild==='seed')el.textContent='Tap a clear patch to plant a glowfern';else el.textContent='Tap a clear patch to place structure';}
  function interact(){nearest();if(!actionTarget){say('Nothing nearby to gather.');return}const n=actionTarget;n.gone=true;world.collected++;if(n.type==='sprout'){inventory.biomass++;say('Living matter collected · +1')}if(n.type==='stone'){inventory.stone++;say('Basalt gathered · +1')}if(n.type==='crystal'){inventory.crystal++;say('Prism crystal collected · +1')}if(n.type==='water'){inventory.water++;say('Pure water sample · +1')}updateUI()}
  function canBuild(type){if(type==='seed')return inventory.seed>=1;if(type==='purifier')return inventory.biomass>=3&&inventory.crystal>=2;if(type==='habitat')return inventory.biomass>=5&&inventory.stone>=3;return false}
